scwin.dts_createStdCdStkInfoStdIsuNm_OnLoadCompleted = function(rowcount) {
    //alert("rowcount " +rowcount);
    /*
4. 신주인수권증서 R
- 한글종목명 : 발행기관명+발행회차+R
- 한글종목약명 : 발행기관약명+발행회차+R
- 영문종목명 : 발행기관명(영)+발행회차+R
- 영문종목약명 : 발행기관명(영)+발행회차+R
* 주권의 기준종목명 테이블에 정보가 있는 경우 그 정보를 가져와 +이후 규칙대로. 

5. 신주인수권증권 WR
- 한글종목명 : 발행기관명+발행회차+WR
- 한글종목약명 : 발행기관약명+발행회차+WR
- 영문종목명 : 발행기관명(영)+발행회차+WR
- 영문종목약명 : 발행기관명(영)+발행회차+WR 
* 주권의 기준종목명 테이블에 정보가 있는 경우 그 정보를 가져와 +이후 규칙대로. 
*/
    if (rowcount == 0) {
        $c.win.alert("해당 주권종류 코드가 존재하지 않습니다.");
        return;
    }
    var A = dts_createStdCdStkInfoStdIsuNm.getCellData(1, "A");
    var B = dts_createStdCdStkInfoStdIsuNm.getCellData(1, "B");
    var C = dts_createStdCdStkInfoStdIsuNm.getCellData(1, "C");
    var D = dts_createStdCdStkInfoStdIsuNm.getCellData(1, "D");
    var E = dts_createStdCdStkInfoStdIsuNm.getCellData(1, "E"); // 기존 주권의 보통주 존재여부

    A = $c.stf.trim(A.replace("보통주", ""));
    B = $c.stf.trim(B.replace("보통주", ""));
    C = $c.stf.trim(C.replace("보통주", ""));
    D = $c.stf.trim(D.replace("보통주", ""));
    var WRNT_ISU_RND = $c.stf.getObjectValue(edt_WRNT_ISU_RND);
    var str_bnd_stkcert_tp_cd = dts_detail.getCellData(dts_detail.rowpositon, "BND_STKCERT_TP_CD");
    var bnd_stkcert_tp_cd = "";
    if (str_bnd_stkcert_tp_cd == "2") {
        bnd_stkcert_tp_cd = WRNT_ISU_RND + "R";
    } else if (str_bnd_stkcert_tp_cd == "1" || str_bnd_stkcert_tp_cd == "3") {
        bnd_stkcert_tp_cd = WRNT_ISU_RND + "WR";
    }
    if (E == "Y") {
        // 	주권에존재 
        txb_ISU_NM.setValue(A);
        txb_ISU_ABBRV.setValue(B);
        txb_ISU_ENG_NM.setValue(C);
        txb_ISU_ENG_ABBRV.setValue(D);
    } else {
        // 	주권에미존재 
        txb_ISU_NM.setValue(A + " " + bnd_stkcert_tp_cd);
        txb_ISU_ABBRV.setValue(B + " " + bnd_stkcert_tp_cd);
        txb_ISU_ENG_NM.setValue(C + " " + bnd_stkcert_tp_cd);
        txb_ISU_ENG_ABBRV.setValue(D + " " + bnd_stkcert_tp_cd);
    }
};
