scwin.cmb_cb_p_group_OnSelChange = function() {
    if ($c.stf.getObjectValue(cmb_cb_p_group) != "") {
        var temp = $c.stf.getObjectValue(cmb_BND_STKCERT_TP_CD); //금융상품구분 R:증서, WR:증권
        var temp2 = "";
        if (temp == "1") {
            //WR증권
            temp2 = "04";
        } else if (temp == "2") {
            //R증서
            temp2 = "05";
        }
        ins_cfi_set(dts_cfi_attr1, scwin.vScrenID, SCREN_PROCS_TP_CD_01, temp2, "R", $c.stf.getObjectValue(cmb_cb_p_group), "1", "");
        ins_cfi_set(dts_cfi_attr2, scwin.vScrenID, SCREN_PROCS_TP_CD_01, temp2, "R", $c.stf.getObjectValue(cmb_cb_p_group), "2", "");
        ins_cfi_set(dts_cfi_attr3, scwin.vScrenID, SCREN_PROCS_TP_CD_01, temp2, "R", $c.stf.getObjectValue(cmb_cb_p_group), "3", "");
        ins_cfi_set(dts_cfi_attr4, scwin.vScrenID, SCREN_PROCS_TP_CD_01, temp2, "R", $c.stf.getObjectValue(cmb_cb_p_group), "4", "");
        //alert(dts_cfi_attr1.NameValue(2,"HEAD_NM"));
        $c.stf.setObjectValue(label_attr1, "(" + dts_cfi_attr1.getCellData(2, "HEAD_NM") + ")");
        $c.stf.setObjectValue(label_attr2, "(" + dts_cfi_attr2.getCellData(2, "HEAD_NM") + ")");
        $c.stf.setObjectValue(label_attr3, "(" + dts_cfi_attr3.getCellData(2, "HEAD_NM") + ")");
        $c.stf.setObjectValue(label_attr4, "(" + dts_cfi_attr4.getCellData(2, "HEAD_NM") + ")");
    }
    scwin.fn_Change_cfi();
};
